import torch

class LinearLayer(torch.nn.Module):
    def __init__(
        self,
        in_features: int = 300,
        out_features: int = 2,
        bias: bool = False,
        seed: int = 23,
    ):
        super().__init__()
        self.lin = torch.nn.Linear(int(in_features), int(out_features), bias=bias)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.lin(x)

